entries[13476] = { ["name"] = "Rezept: Mächtiger Wuttrank", ["text"] = "Benötigt Alchemie\n(255)\nBenutzen: Lehrt Euch die Herstellung eines mächtigen Wuttranks.\nVerkaufspreis:\nMächtiger Wuttrank\nKlassen: Krieger , Druide\nBenötigt Stufe 46\nBenutzen: Erzeugt sofort 45 bis 75 Wut und erhöht Stärke 20 Sek. lang um 60 . (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Gromsblut (3), Kristallphiole" }
