entries[13503] = { ["name"] = "Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Stärke\n+15 Beweglichkeit\n+15 Ausdauer\n+15 Intelligenz\n+15 Willenskraft\nBenötigt Alchemie\n(350)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[13505] = { ["name"] = "Runenklinge von Baron Totenschwur", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n145 - 219 Schaden Tempo 3.60\n(50.56 Schaden pro Sekunde)\nHaltbarkeit 120 / 120\nBenötigt Stufe 48\nAnlegen: Erhöht Bewegungstempo und Gesundheitsregenerationsrate.\nVerkaufspreis:" }
entries[13506] = { ["name"] = "Trank der Versteinerung", ["text"] = "Benötigt Stufe 50\nBenutzen: Ihr werdet zu Stein und absorbiert 6000 Schaden aus jeglicher Schadensquelle, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen oder Zauber wirken. Hält 30 Sek. lang an. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[13507] = { ["name"] = "Klippenbehüter Langhorns Bericht", ["text"] = "Questgegenstand\nEinzigartig\n<Zum Lesen rechtsklicken>" }
entries[13508] = { ["name"] = "Auge von Arachnida", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Beschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge ist getarnt und bewegt sich schnell, ist jedoch sehr fragil. (1 Min Abklingzeit)\n3 Aufladungen\nVerkaufspreis:" }
entries[13509] = { ["name"] = "Klammer der Voraussicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Kontert das Zauberwirken des Feindes und verhindert 10 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung. Es besteht die Chance eines Fehlschlags, wenn das Ziel über Stufe 60 ist. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[13510] = { ["name"] = "Fläschchen der Titanen", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 400 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[13511] = { ["name"] = "Fläschchen der destillierten Weisheit", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 65 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[13512] = { ["name"] = "Fläschchen der obersten Macht", ["text"] = "Benötigt Stufe 50\nBenutzen: Erhöht die Zaubermacht 1 Stunde lang um 70 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[13513] = { ["name"] = "Fläschchen des chromatischen Widerstands", ["text"] = "Benötigt Stufe 50\nVerkaufspreis:" }
entries[13514] = { ["name"] = "Wehklage der Banshee", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 55\nBenutzen: Verringert die Chance eines Feindes zu treffen 12 Sek. lang um 10%. Es besteht die Chance, dass der Effekt gegen Ziele über Stufe 60 nicht wirkt. (1 Min Abklingzeit)\n3 Aufladungen\nVerkaufspreis:" }
entries[13515] = { ["name"] = "Ramsteins Blitzbolzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Trefferwertung um + 8.\nBenötigt Stufe 48\nBenutzen: Setzt die Macht des Blitzschlags ein, um allen Feinden um Euch herum 260 Naturschaden zuzufügen. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[13517] = { ["name"] = "Rezept: Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(350)\nBenötigt Die Sha'tar\n- Respektvoll\nBenutzen: Lehrt Euch die Herstellung eines Alchemistensteins.\nVerkaufspreis:\nAlchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Stärke\n+15 Beweglichkeit\n+15 Ausdauer\n+15 Intelligenz\n+15 Willenskraft\nBenötigt Alchemie\n(350)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Stein der Weisen , Erdsturmdiamant , Himmelsfeuerdiamant , Teufelslotus (2), Urmacht (5)" }
entries[13518] = { ["name"] = "Rezept: Trank der Versteinerung", ["text"] = "Benötigt Alchemie\n(300)\nBenutzen: Lehrt Euch die Herstellung eines Tranks der Versteinerung.\nVerkaufspreis:\nTrank der Versteinerung\nBenötigt Stufe 50\nBenutzen: Ihr werdet zu Stein und absorbiert 6000 Schaden aus jeglicher Schadensquelle, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen oder Zauber wirken. Hält 30 Sek. lang an. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Steinschuppenöl (7), Kristallphiole" }
entries[13519] = { ["name"] = "Rezept: Fläschchen der Titanen", ["text"] = "Benötigt Alchemie\n(300)\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der Titanen.\nVerkaufspreis:\nFläschchen der Titanen\nBenötigt Stufe 50\nBenutzen: Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 400 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Gromsblut (7), Steinschuppenöl (3), Schwarzer Lotus , Kristallphiole" }
entries[13520] = { ["name"] = "Rezept: Fläschchen der destillierten Weisheit", ["text"] = "Benötigt Alchemie\n(300)\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der destillierten Weisheit.\nVerkaufspreis:\nFläschchen der destillierten Weisheit\nBenötigt Stufe 50\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 65 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (7), Eiskappe (3), Schwarzer Lotus , Kristallphiole" }
entries[13521] = { ["name"] = "Rezept: Fläschchen der obersten Macht", ["text"] = "Benötigt Alchemie\n(300)\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der obersten Macht.\nVerkaufspreis:\nFläschchen der obersten Macht\nBenötigt Stufe 50\nBenutzen: Erhöht die Zaubermacht 1 Stunde lang um 70 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (7), Bergsilbersalbei (3), Schwarzer Lotus , Kristallphiole" }
